fn resolve_account(id: &str) -> Option<[u8; 32]> {
    let account = hex::account_id_bytes(id);
    if account.is_none() {
        eprintln!("{id} is neither 32-byte hex nor a base58 account id");
    }
    account
}

fn resolve_account_id(id: &str) -> String {
    resolve_account(id)
        .map(|account| bytes_to_hex(&account))
        .unwrap_or_default()
}

const NATIVE_TOKEN_PROGRAM: [u8; 32] = [0; 32];

enum FetchOutcome {
    Present(Vec<u8>),
    Absent,
    Error,
}

fn fetch_actor_states(account_id: &[u8; 32]) -> Option<Vec<([u8; 32], Vec<u8>)>> {
    match wallet::read_account(account_id) {
        wallet::AccountRead::Present(states) => Some(states),
        wallet::AccountRead::Absent => Some(Vec::new()),
        wallet::AccountRead::Error => None,
    }
}

fn fetch_shard_tri_state(account_id: &[u8; 32], program: &[u8; 32]) -> FetchOutcome {
    let Some(states) = fetch_actor_states(account_id) else {
        return FetchOutcome::Error;
    };
    match states.into_iter().find(|(p, _)| p == program) {
        Some((_, data)) if !data.is_empty() => FetchOutcome::Present(data),
        _ => FetchOutcome::Absent,
    }
}

fn fetch_shard_quiet(account_id: &[u8; 32], program: &[u8; 32]) -> Option<Vec<u8>> {
    match fetch_shard_tri_state(account_id, program) {
        FetchOutcome::Present(data) => Some(data),
        _ => None,
    }
}

fn fetch_shard(account_id: &[u8; 32], program: &[u8; 32], who: &str) -> Option<Vec<u8>> {
    match fetch_shard_tri_state(account_id, program) {
        FetchOutcome::Present(data) => Some(data),
        FetchOutcome::Absent => {
            eprintln!(
                "{who}: {} holds no state of program {}",
                bytes_to_hex(account_id),
                bytes_to_hex(program)
            );
            None
        }
        FetchOutcome::Error => {
            eprintln!("{who}: reading {} failed", bytes_to_hex(account_id));
            None
        }
    }
}

struct RlnConfigContext {
    config_account: [u8; 32],
    config_data: Vec<u8>,
    registration_program: [u8; 32],
    merkle_program: [u8; 32],
}

struct RegistryProblem {
    status: &'static str,
    detail: String,
}

impl RegistryProblem {
    fn new(status: &'static str, detail: String) -> Self {
        Self { status, detail }
    }
}

fn resolve_config_context(config_account_id: &str, who: &str) -> Option<RlnConfigContext> {
    logged_context(
        config_account(config_account_id).and_then(|config| config_context(&config)),
        who,
    )
}

fn logged_context(
    context: Result<RlnConfigContext, RegistryProblem>,
    who: &str,
) -> Option<RlnConfigContext> {
    context.map_err(|p| eprintln!("{who}: {}", p.detail)).ok()
}

fn config_account(config_account_id: &str) -> Result<[u8; 32], RegistryProblem> {
    resolve_account(config_account_id).ok_or_else(|| {
        RegistryProblem::new(
            "invalid",
            format!("'{config_account_id}' is not an account id"),
        )
    })
}

fn config_context(config: &[u8; 32]) -> Result<RlnConfigContext, RegistryProblem> {
    let config_hex = bytes_to_hex(config);
    if let Some(reason) = network_conflict(wallet::bound_network().as_deref(), &config_hex) {
        return Err(RegistryProblem::new("network_conflict", reason));
    }
    let Some(states) = fetch_actor_states(config) else {
        return Err(RegistryProblem::new(
            "unreachable",
            format!("could not read config account {config_hex} from the sequencer"),
        ));
    };
    let mut program_shards = states
        .into_iter()
        .filter(|(p, data)| *p != NATIVE_TOKEN_PROGRAM && !data.is_empty());
    let Some((registration_program, config_data)) = program_shards.next() else {
        return Err(RegistryProblem::new(
            "not_deployed",
            format!(
                "config account {config_hex} holds no program state on this chain — the registry \
                 is not deployed here (the network may have been reset)"
            ),
        ));
    };
    if program_shards.next().is_some() {
        return Err(RegistryProblem::new(
            "unexpected_layout",
            format!("config account {config_hex} holds more than one program's state"),
        ));
    }
    if config_data.len() != native::CONFIG_STATE_SIZE {
        return Err(RegistryProblem::new(
            "wrong_generation",
            format!(
                "config state is {} bytes, expected {} — this is a config from a different \
                 program generation, not a short read",
                config_data.len(),
                native::CONFIG_STATE_SIZE,
            ),
        ));
    }
    let merkle_program =
        native::config_field_32(&config_data, native::CONFIG_OFFSET_MERKLE_PROGRAM_ID);
    Ok(RlnConfigContext {
        config_account: *config,
        config_data,
        registration_program,
        merkle_program,
    })
}

fn network_conflict(bound: Option<&str>, config_hex: &str) -> Option<String> {
    let bound = bound?;
    let listed = networks::network_of_config(config_hex)?;
    (listed.reference != bound).then(|| {
        format!(
            "config account {config_hex} is on network {}, but this wallet is bound to {bound}",
            listed.reference
        )
    })
}

fn fee_payer_hex() -> &'static str {
    wallet::payer_hex()
}

fn send_generic_tx(
    who: &str,
    mentions: &[wallet::Mention],
    root: usize,
    message: &[u8],
    payer_hex: &str,
) -> Result<wallet::SendResult, String> {
    let accepted = wallet::send_generic_public_transaction(mentions, root, message, payer_hex)
        .ok_or_else(|| "no reply from the wallet".to_string())
        .and_then(wallet::SendResult::accepted);
    if let Err(why) = &accepted {
        eprintln!("{who}: transaction failed: {why}");
    }
    accepted
}

fn derive_register_plan(
    ctx: &RlnConfigContext,
    id_commitment: &[u8; 32],
    who: &str,
) -> Option<RlnRegisterPlan> {
    let tree_main = match native::tree_main_account_id(&ctx.config_data, &ctx.registration_program)
    {
        Ok(id) => id,
        Err(e) => {
            eprintln!("{who}: derive tree main failed: {e}");
            return None;
        }
    };
    let tree_main_data = fetch_shard(&tree_main, &ctx.merkle_program, who)?;
    match native::register_plan(
        &ctx.config_data,
        &tree_main_data,
        &ctx.registration_program,
        id_commitment,
    ) {
        Ok(plan) => Some(plan),
        Err(e) => {
            eprintln!("{who}: register_plan failed: {e}");
            None
        }
    }
}

fn chain_time_ms(who: &str) -> Option<u64> {
    let time = fee_state::head_block_timestamp_ms();
    if time.is_none() {
        eprintln!("{who}: chain time unavailable");
    }
    time
}

const CHAIN_TIME_SLACK_MS: u64 = 5_000;

fn membership_leaf_index(
    ctx: &RlnConfigContext,
    membership: &rln_layouts::MembershipState,
    who: &str,
) -> Option<u64> {
    let tree = fetch_tree_shard(ctx, who)?;
    let Some(leaf) = native::registration_leaf(&membership.id_commitment, membership.rate_limit)
    else {
        eprintln!("{who}: the membership's id_commitment is not a field element");
        return None;
    };
    let found = native::find_leaf_index(&tree, &leaf);
    if found.is_none() {
        eprintln!("{who}: the tree holds no leaf for this membership");
    }
    found
}

fn fetch_tree_shard(ctx: &RlnConfigContext, who: &str) -> Option<Vec<u8>> {
    let main = match native::tree_main_account_id(&ctx.config_data, &ctx.registration_program) {
        Ok(id) => id,
        Err(e) => {
            eprintln!("{who}: derive tree main failed: {e}");
            return None;
        }
    };
    fetch_shard(&main, &ctx.merkle_program, who)
}

fn roots_to_json_array(roots: &[[u8; 32]]) -> serde_json::Value {
    serde_json::Value::Array(
        roots
            .iter()
            .map(|r| serde_json::Value::String(bytes_to_hex(r)))
            .collect(),
    )
}

#[derive(serde::Serialize)]
struct ProofWithRoots<'a> {
    depth: u32,
    leaf: &'a str,
    leaf_index: u64,
    path_elements: &'a [String],
    path_indices: &'a [u8],
    root: &'a str,
    valid_roots: &'a serde_json::Value,
}

fn proofs_with_roots_json(proofs: &[native::ProofJson], roots_array: &serde_json::Value) -> String {
    let augmented: Vec<ProofWithRoots<'_>> = proofs
        .iter()
        .map(|p| ProofWithRoots {
            depth: p.depth,
            leaf: &p.leaf,
            leaf_index: p.leaf_index,
            path_elements: &p.path_elements,
            path_indices: &p.path_indices,
            root: &p.root,
            valid_roots: roots_array,
        })
        .collect();
    serde_json::to_string(&augmented).unwrap_or_default()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Yes;

impl serde::Serialize for Yes {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_bool(true)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(untagged)]
enum RegisterReply {
    Submitted {
        leaf_index: u64,
        pending: Yes,
        rate_limit: u64,
        #[serde(skip_serializing_if = "Option::is_none")]
        tx_result: Option<String>,
    },
    AlreadyRegistered {
        already_registered: Yes,
        leaf_index: u64,
    },
    Refused {
        error: String,
    },
}

impl RegisterReply {
    fn pending(leaf_index: u64, rate_limit: u64, sent: Option<&wallet::SendResult>) -> Self {
        Self::Submitted {
            leaf_index,
            pending: Yes,
            rate_limit,
            tx_result: sent.map(wallet::SendResult::to_json),
        }
    }

    fn refused(why: impl Into<String>) -> Self {
        Self::Refused { error: why.into() }
    }

    fn to_json(&self) -> String {
        serde_json::to_value(self)
            .map(|v| v.to_string())
            .unwrap_or_default()
    }
}

fn submit_register(
    ctx: &RlnConfigContext,
    plan: &RlnRegisterPlan,
    id_commitment: &[u8; 32],
    rate_limit: u64,
    payer_hex: &str,
    who: &str,
) -> Result<wallet::SendResult, String> {
    let Some(payer) = hex_to_bytes32(payer_hex) else {
        eprintln!("{who}: payer {payer_hex} is not 32-byte hex");
        return Err(format!("payer {payer_hex} is not 32-byte hex"));
    };
    let now_ms = chain_time_ms(who)
        .ok_or_else(|| "chain time unavailable".to_string())?
        .saturating_sub(CHAIN_TIME_SLACK_MS);
    let message =
        match native::register_build_message(plan, id_commitment, rate_limit, &payer, now_ms) {
            Ok(bytes) => bytes,
            Err(e) => {
                eprintln!("{who}: register_build_message failed: {e}");
                return Err(format!("register_build_message failed: {e}"));
            }
        };
    use wallet::MentionKind::{NoSign, Pda, Signer};
    let mention = |account: [u8; 32], program: [u8; 32], kind| wallet::Mention {
        account,
        program,
        kind,
    };
    let mentions = [
        mention(plan.config_account_id, ctx.registration_program, NoSign),
        mention(
            plan.membership_account_id,
            ctx.registration_program,
            Pda {
                program: ctx.registration_program,
                seed: rln_layouts::membership_seed(&plan.tree_id, id_commitment),
            },
        ),
        mention(plan.tree_main_account_id, plan.merkle_program_id, NoSign),
        mention(payer, NATIVE_TOKEN_PROGRAM, Signer),
        mention(plan.treasury_account_id, NATIVE_TOKEN_PROGRAM, NoSign),
    ];
    send_generic_tx(who, &mentions, 0, &message, fee_payer_hex())
}

const REG_WATCH_INTERVAL: Duration = Duration::from_secs(2);
const REG_MAX_RESUBMITS: u32 = 5;
const REG_DROPPED_POLLS: u32 = 60;

struct RegisterWatch {
    config_account: [u8; 32],
    payer_hex: String,
    id_commitment: [u8; 32],
    rate_limit: u64,
    reg_key: [u8; 32],
    tx_hash: String,
}

const REGISTER_DATA_ALLOWANCE: u128 = 100_000;

fn preflight_register(
    ctx: &RlnConfigContext,
    plan: &RlnRegisterPlan,
    id_commitment: &[u8; 32],
    rate_limit: u64,
    payer_hex: &str,
) -> Result<(), String> {
    native::check_register(
        &ctx.config_data,
        plan.next_leaf_index,
        id_commitment,
        rate_limit,
    )?;
    if let wallet::AccountRead::Absent = wallet::read_account(&plan.treasury_account_id) {
        return Err(format!(
            "treasury_missing: the registry's treasury {} does not exist on this chain; run_setup \
             seeds it",
            bytes_to_hex(&plan.treasury_account_id)
        ));
    }
    let quote = fee_state::fee_quote();
    let ceiling = |key: &str| {
        quote
            .as_ref()
            .and_then(|q| q.get(key))
            .and_then(serde_json::Value::as_u64)
            .map(u128::from)
    };
    let (Some(exec), Some(stor)) = (
        ceiling("next_base_fee_exec_ceiling"),
        ceiling("next_base_fee_stor_ceiling"),
    ) else {
        return Ok(());
    };
    let Some((_, balance)) = wallet::native_balance(payer_hex) else {
        return Ok(());
    };
    let price = plan.price_per_unit.saturating_mul(u128::from(rate_limit));
    let reserve = u128::from(wallet::GAS_LIMIT)
        .saturating_mul(exec)
        .saturating_add(REGISTER_DATA_ALLOWANCE.saturating_mul(stor));
    let needed = price.saturating_add(reserve);
    if !can_afford(balance, price, reserve) {
        return Err(format!(
            "insufficient_balance: payer {payer_hex} holds {balance}, a registration needs {needed} \
             ({price} price + {reserve} fee reserve at the next block's base fee ceiling)"
        ));
    }
    Ok(())
}

fn spawn_register_watch(w: RegisterWatch) {
    let spawned = std::thread::Builder::new()
        .name("lez-rln-register-watch".into())
        .spawn(move || register_watch(w));
    if let Err(e) = spawned {
        eprintln!("register_member: could not start the confirmation watcher: {e}");
    }
}

fn register_watch(mut w: RegisterWatch) {
    const WHO: &str = "register_member(watch)";
    let deadline = Instant::now() + REG_IN_FLIGHT_TTL;
    let mut resubmits = 0u32;
    let mut not_included = 0u32;
    while Instant::now() < deadline {
        std::thread::sleep(REG_WATCH_INTERVAL);
        let Some(ctx) = logged_context(config_context(&w.config_account), WHO) else {
            continue;
        };
        let Some(plan) = derive_register_plan(&ctx, &w.id_commitment, WHO) else {
            continue;
        };
        let landed = || {
            fetch_shard_quiet(&plan.membership_account_id, &ctx.registration_program)
                .and_then(|data| native::decode_membership(&data).ok())
        };
        if let Some(m) = landed() {
            match membership_leaf_index(&ctx, &m, WHO) {
                Some(leaf) => eprintln!("{WHO}: registered at leaf {leaf}"),
                None => eprintln!("{WHO}: registered"),
            }
            return;
        }
        match fee_state::tx_included(&w.tx_hash) {
            Some(true) => not_included = 0,
            Some(false) => {
                not_included += 1;
                if not_included < REG_DROPPED_POLLS {
                    continue;
                }
                not_included = 0;
                eprintln!(
                    "{WHO}: tx {} not included after {REG_DROPPED_POLLS} polls — dropped at the door; \
                     re-sending",
                    w.tx_hash
                );
            }
            None => continue,
        }
        if landed().is_some() {
            continue;
        }
        if resubmits >= REG_MAX_RESUBMITS {
            eprintln!(
                "{WHO}: membership still absent after {REG_MAX_RESUBMITS} re-sends — giving up; \
                 a later register_member call starts afresh"
            );
            reg_in_flight(|m| m.remove(&w.reg_key));
            return;
        }
        if let Err(why) =
            preflight_register(&ctx, &plan, &w.id_commitment, w.rate_limit, &w.payer_hex)
        {
            eprintln!(
                "{WHO}: tx {} reverted and a re-send would too — not re-sending: {why}",
                w.tx_hash
            );
            reg_in_flight(|m| m.insert(w.reg_key, (RegisterReply::refused(why), Instant::now())));
            return;
        }
        eprintln!(
            "{WHO}: tx {} is in a block but registered nothing — it reverted; re-sending dated \
             by chain time now",
            w.tx_hash
        );
        resubmits += 1;
        let send_result = match submit_register(
            &ctx,
            &plan,
            &w.id_commitment,
            w.rate_limit,
            &w.payer_hex,
            WHO,
        ) {
            Ok(r) => r,
            Err(_) => continue,
        };
        let reply = RegisterReply::pending(plan.next_leaf_index, w.rate_limit, Some(&send_result));
        w.tx_hash = send_result.into_tx_hash();
        reg_in_flight(|m| m.insert(w.reg_key, (reply, Instant::now())));
    }
    reg_in_flight(|m| m.remove(&w.reg_key));
    eprintln!(
        "{WHO}: no membership within {}s",
        REG_IN_FLIGHT_TTL.as_secs()
    );
}

fn get_valid_roots_impl(rln_account_id_hex: &str) -> String {
    let Some(ctx) = resolve_config_context(rln_account_id_hex, "get_valid_roots") else {
        return String::new();
    };

    let Some(main_data) = fetch_tree_shard(&ctx, "get_valid_roots") else {
        return String::new();
    };

    let roots = match native::get_valid_roots(&main_data) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("get_valid_roots: valid_roots_from_main failed: {e}");
            return String::new();
        }
    };

    let depth = match native::tree_depth(&main_data) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("get_valid_roots: tree depth unreadable: {e}");
            return String::new();
        }
    };

    serde_json::json!({ "depth": depth, "valid_roots": roots_to_json_array(&roots) }).to_string()
}

fn get_merkle_proofs_impl(config_account_id: &str, leaf_indices_json: &str) -> String {
    let indices_doc = serde_json::from_str::<serde_json::Value>(leaf_indices_json).ok();
    let Some(indices_array) = indices_doc.as_ref().and_then(|v| v.as_array()) else {
        eprintln!("get_merkle_proofs: leaf_indices_json is not a JSON array");
        return String::new();
    };
    if indices_array.is_empty() {
        return "[]".to_string();
    }
    let mut leaf_indices: Vec<u64> = Vec::with_capacity(indices_array.len());
    for val in indices_array {
        if !val.is_number() {
            eprintln!("get_merkle_proofs: leaf index is not a number");
            return String::new();
        }
        let idx = val
            .as_u64()
            .or_else(|| val.as_i64().map(|v| v as u64))
            .or_else(|| val.as_f64().map(|v| v as u64))
            .unwrap_or(0);
        leaf_indices.push(idx);
    }

    let Some(ctx) = resolve_config_context(config_account_id, "get_merkle_proofs") else {
        return String::new();
    };

    let Some(main_data) = fetch_tree_shard(&ctx, "get_merkle_proofs") else {
        return String::new();
    };
    let roots = match native::get_valid_roots(&main_data) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("get_merkle_proofs: valid_roots failed: {e}");
            return String::new();
        }
    };
    let proofs = match native::merkle_proofs_exec(&main_data, &leaf_indices) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("get_merkle_proofs: merkle_proofs_exec failed: {e}");
            return String::new();
        }
    };

    proofs_with_roots_json(&proofs, &roots_to_json_array(&roots))
}

#[derive(Default)]
struct RlnLezModuleImpl;

impl RlnLezModule for RlnLezModuleImpl {
    fn get_native_balance(&self, account_id: String) -> String {
        let Some((account, balance)) = wallet::native_balance(&account_id) else {
            return String::new();
        };
        serde_json::json!({
            "account": account,
            "balance": balance.to_string(),
        })
        .to_string()
    }

    fn wallet_status(&self) -> String {
        wallet::status_json()
    }

    fn use_network(&self, reference: String) -> String {
        wallet::use_network(&reference)
    }

    fn get_fee_state(&self) -> String {
        fee_state::get_fee_state()
    }

    fn on_context_ready(&self, ctx: &RustModuleContext) {
        wallet::spawn_bring_up(&ctx.instance_persistence_path);
    }

    fn get_valid_roots(&self, rln_account_id_hex: String) -> String {
        get_valid_roots_impl(&rln_account_id_hex)
    }

    fn get_merkle_proofs(&self, config_account_id: String, leaf_indices_json: String) -> String {
        get_merkle_proofs_impl(&config_account_id, &leaf_indices_json)
    }

    fn register_member(
        &self,
        config_account_id: String,
        payer_account_id: String,
        id_commitment_hex: String,
        rate_limit: i64,
    ) -> String {
        let Ok(rate_limit) = u64::try_from(rate_limit) else {
            eprintln!("register_member: negative rate_limit {rate_limit}");
            return RegisterReply::refused(format!("invalid_rate_limit: {rate_limit} is negative"))
                .to_json();
        };
        let Some(id_commitment) = hex_to_bytes32(&id_commitment_hex) else {
            eprintln!("register_member: invalid id_commitment hex");
            return String::new();
        };

        let Some(ctx) = resolve_config_context(&config_account_id, "register_member") else {
            return String::new();
        };

        let payer_hex = if payer_account_id.trim().is_empty() {
            wallet::payer_hex().to_owned()
        } else {
            resolve_account_id(&payer_account_id)
        };
        if payer_hex.is_empty() {
            eprintln!("register_member: no payer — the wallet has not resolved one yet");
            return String::new();
        }

        let Some(plan) = derive_register_plan(&ctx, &id_commitment, "register_member") else {
            return String::new();
        };

        if let Some(membership) =
            fetch_shard_quiet(&plan.membership_account_id, &ctx.registration_program)
                .and_then(|existing| native::decode_membership(&existing).ok())
        {
            let Some(leaf) = membership_leaf_index(&ctx, &membership, "register_member") else {
                return String::new();
            };
            eprintln!(
                "register_member: membership already exists at leaf {leaf} — skipping resubmit"
            );
            return RegisterReply::AlreadyRegistered {
                already_registered: Yes,
                leaf_index: leaf,
            }
            .to_json();
        }

        if let Err(why) = preflight_register(&ctx, &plan, &id_commitment, rate_limit, &payer_hex) {
            eprintln!("register_member: not submitting: {why}");
            return RegisterReply::refused(why).to_json();
        }

        let reg_key = plan.membership_account_id;
        let placeholder = RegisterReply::pending(plan.next_leaf_index, rate_limit, None);
        let prior = reg_in_flight(|m| match m.get(&reg_key) {
            Some((reply, _)) => {
                let prior_rate = match reply {
                    RegisterReply::Submitted { rate_limit: r, .. } => Some(*r),
                    _ => None,
                };
                Some((prior_rate, reply.to_json()))
            }
            None => {
                m.insert(reg_key, (placeholder, Instant::now()));
                None
            }
        });
        if let Some((prior_rate, prior_json)) = prior {
            match prior_rate {
                Some(r) if r != rate_limit => eprintln!(
                    "register_member: registration already submitted this session at rate {r}, \
                     not the requested {rate_limit} — returning prior reply"
                ),
                _ => eprintln!(
                    "register_member: registration already submitted this session — returning prior reply"
                ),
            }
            return prior_json;
        }

        let send_result = match submit_register(
            &ctx,
            &plan,
            &id_commitment,
            rate_limit,
            &payer_hex,
            "register_member",
        ) {
            Ok(r) => r,
            Err(why) => {
                reg_in_flight(|m| m.remove(&reg_key));
                return RegisterReply::refused(format!("send_failed: {why}")).to_json();
            }
        };

        let reply = RegisterReply::pending(plan.next_leaf_index, rate_limit, Some(&send_result));
        let reply_json = reply.to_json();
        reg_in_flight(|m| m.insert(reg_key, (reply, Instant::now())));
        spawn_register_watch(RegisterWatch {
            config_account: ctx.config_account,
            payer_hex,
            id_commitment,
            rate_limit,
            reg_key,
            tx_hash: send_result.into_tx_hash(),
        });
        reply_json
    }

    fn get_membership(&self, config_account_id: String, id_commitment_hex: String) -> String {
        let Some(id_commitment) = hex_to_bytes32(&id_commitment_hex) else {
            eprintln!("get_membership: invalid id_commitment hex");
            return String::new();
        };

        let Some(ctx) = resolve_config_context(&config_account_id, "get_membership") else {
            return String::new();
        };
        let Some(plan) = derive_register_plan(&ctx, &id_commitment, "get_membership") else {
            return String::new();
        };

        let data =
            match fetch_shard_tri_state(&plan.membership_account_id, &ctx.registration_program) {
                FetchOutcome::Present(data) => data,
                FetchOutcome::Absent => {
                    return serde_json::json!({ "registered": false }).to_string();
                }
                FetchOutcome::Error => {
                    eprintln!(
                        "get_membership: membership PDA fetch failed for {}",
                        bytes_to_hex(&plan.membership_account_id)
                    );
                    return String::new();
                }
            };
        let membership = match native::decode_membership(&data) {
            Ok(m) => m,
            Err(e) => {
                eprintln!("get_membership: membership decode error: {e}");
                return String::new();
            }
        };

        let Some(now_ms) = chain_time_ms("get_membership") else {
            return String::new();
        };
        let Some(leaf_index) = membership_leaf_index(&ctx, &membership, "get_membership") else {
            return String::new();
        };

        serde_json::json!({
            "clock_timestamp": now_ms,
            "grace_period_duration": membership.grace_period_duration_sec,
            "grace_period_start_timestamp": membership.grace_period_start_timestamp_ms,
            "leaf_index": leaf_index as i64,
            "rate_limit": membership.rate_limit as i64,
            "registered": true,
            "state": native::membership_status(
                membership.grace_period_start_timestamp_ms,
                membership.grace_period_duration_sec,
                now_ms,
            ),
        })
        .to_string()
    }

    fn check_registry(&self, config_account_id: String) -> String {
        let mut out = match config_account(&config_account_id).and_then(|c| config_context(&c)) {
            Ok(ctx) => serde_json::json!({
                "status": "ok",
                "registration_program": bytes_to_hex(&ctx.registration_program),
            }),
            Err(p) => serde_json::json!({"status": p.status, "detail": p.detail}),
        };
        if let Some(sequencer) = wallet::sequencer_addr() {
            out["sequencer"] = serde_json::json!(sequencer);
        }
        if let Some(head) = fee_state::chain_head() {
            out["chain_head"] = serde_json::json!(head);
        }
        out.to_string()
    }

    fn get_registry_bounds(&self, config_account_id: String) -> String {
        let Some(ctx) = resolve_config_context(&config_account_id, "get_registry_bounds") else {
            return String::new();
        };
        let cfg = &ctx.config_data;
        serde_json::json!({
            "active_duration":
                native::config_field_u32(cfg, native::CONFIG_OFFSET_ACTIVE_DURATION),
            "current_total_rate_limit":
                native::config_field_u64(cfg, native::CONFIG_OFFSET_CURRENT_TOTAL_RATE_LIMIT),
            "grace_period_duration":
                native::config_field_u32(cfg, native::CONFIG_OFFSET_GRACE_DURATION),
            "max_rate_limit": native::config_field_u64(cfg, native::CONFIG_OFFSET_MAX_RATE_LIMIT),
            "max_total_rate_limit":
                native::config_field_u64(cfg, native::CONFIG_OFFSET_MAX_TOTAL_RATE_LIMIT),
            "min_rate_limit": native::config_field_u64(cfg, native::CONFIG_OFFSET_MIN_RATE_LIMIT),
            "price_per_unit":
                native::config_field_u128(cfg, native::CONFIG_OFFSET_PRICE_PER_UNIT).to_string(),
            "total_registrations":
                native::config_field_u64(cfg, native::CONFIG_OFFSET_TOTAL_REGISTRATIONS),
        })
        .to_string()
    }
}

#[expect(
    unsafe_code,
    reason = "#[no_mangle]: the generated __logos_install_hook resolves this symbol by linkage"
)]
#[no_mangle]
pub extern "Rust" fn logos_module_install() {
    install::<RlnLezModuleImpl>();
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hex::{canonical_account_hex, hex_to_bytes};

    #[test]
    fn an_account_id_has_one_canonical_form() {
        let lower = "ab".repeat(32);
        let canonical = canonical_account_hex(&lower);
        assert_eq!(canonical.as_deref(), Some(lower.as_str()));
        assert_eq!(
            canonical_account_hex(&format!("0x{}", "AB".repeat(32))),
            canonical
        );
        assert_eq!(canonical_account_hex(&format!(" 0X{lower} ")), canonical);
        assert_eq!(canonical_account_hex(&"zz".repeat(32)), None);
    }

    #[test]
    fn hex_roundtrip_mirrors_cpp_hex_to_bytes() {
        let hex = "00".repeat(31) + "ff";
        let b = hex_to_bytes32(&hex).unwrap();
        assert_eq!(b[31], 0xff);
        assert_eq!(bytes_to_hex(&b), hex);
        assert!(hex_to_bytes32(&(String::from("0x") + &hex)).is_some());
        assert!(hex_to_bytes32("zz").is_none());
        assert!(hex_to_bytes("abc", None).is_none());
        assert_eq!(hex_to_bytes(" 00ff ", None).unwrap(), vec![0x00, 0xff]);
    }

    #[test]
    fn register_replies_serialise_to_the_wire_text() {
        let placeholder = RegisterReply::pending(5, 100, None);
        assert_eq!(
            placeholder.to_json(),
            r#"{"leaf_index":5,"pending":true,"rate_limit":100}"#
        );
        let submitted = RegisterReply::Submitted {
            leaf_index: 5,
            pending: Yes,
            rate_limit: 100,
            tx_result: Some(r#"{"error":"","success":true,"tx_hash":"ab12"}"#.into()),
        };
        assert_eq!(
            submitted.to_json(),
            r#"{"leaf_index":5,"pending":true,"rate_limit":100,"tx_result":"{\"error\":\"\",\"success\":true,\"tx_hash\":\"ab12\"}"}"#
        );
        let already = RegisterReply::AlreadyRegistered {
            already_registered: Yes,
            leaf_index: 7,
        };
        assert_eq!(
            already.to_json(),
            r#"{"already_registered":true,"leaf_index":7}"#
        );
        assert_eq!(
            RegisterReply::refused("send_failed: key not found").to_json(),
            r#"{"error":"send_failed: key not found"}"#
        );
    }

    #[test]
    fn a_negative_rate_is_refused_as_invalid_rate_limit() {
        let reply =
            RlnLezModuleImpl.register_member(String::new(), String::new(), "00".repeat(32), -1);
        assert_eq!(reply, r#"{"error":"invalid_rate_limit: -1 is negative"}"#);
    }

    #[test]
    fn reg_in_flight_entries_expire_after_ttl() {
        let stale_key = [0xaa_u8; 32];
        let fresh_key = [0xbb_u8; 32];
        let Some(back_dated) =
            Instant::now().checked_sub(REG_IN_FLIGHT_TTL + Duration::from_secs(1))
        else {
            eprintln!("reg_in_flight ttl test: uptime too short to back-date; skipping");
            return;
        };
        reg_in_flight(|m| {
            m.insert(stale_key, (RegisterReply::refused("stale"), back_dated));
            m.insert(fresh_key, (RegisterReply::refused("fresh"), Instant::now()));
        });
        reg_in_flight(|m| {
            assert!(!m.contains_key(&stale_key), "stale entry must be evicted");
            assert_eq!(
                m.get(&fresh_key).map(|(r, _)| r),
                Some(&RegisterReply::refused("fresh"))
            );
            m.remove(&fresh_key);
        });
    }

    #[test]
    fn can_afford_requires_the_balance_to_cover_price_plus_fee_reserve() {
        let (price, reserve) = (1_000_u128, 50_u128);
        assert!(can_afford(1_050, price, reserve));
        assert!(!can_afford(1_049, price, reserve));
        assert!(!can_afford(1_000, price, reserve));
        assert!(can_afford(10_000, price, reserve));
        assert!(!can_afford(100, price, reserve));
        assert!(!can_afford(u128::MAX - 1, u128::MAX, 1));
        assert!(can_afford(u128::MAX, u128::MAX, 1));
    }

    #[test]
    fn augmented_proofs_match_json_roundtrip() {
        let proofs = vec![native::ProofJson {
            leaf: "aa".repeat(32),
            root: "bb".repeat(32),
            leaf_index: 5,
            depth: 2,
            path_elements: vec!["cc".repeat(32), "dd".repeat(32)],
            path_indices: vec![1, 0],
        }];
        let roots_array = roots_to_json_array(&[[0xEE; 32]]);

        let legacy_json = serde_json::to_string(&proofs).unwrap();
        let legacy_parsed = serde_json::from_str::<serde_json::Value>(&legacy_json)
            .ok()
            .and_then(|v| v.as_array().cloned())
            .unwrap_or_default();
        let legacy: Vec<serde_json::Value> = legacy_parsed
            .into_iter()
            .map(|p| {
                let mut obj = p.as_object().cloned().unwrap_or_default();
                obj.insert("valid_roots".to_string(), roots_array.clone());
                serde_json::Value::Object(obj)
            })
            .collect();
        let legacy_str = serde_json::Value::Array(legacy).to_string();

        let current_str = proofs_with_roots_json(&proofs, &roots_array);
        assert_eq!(current_str, legacy_str);
        assert!(current_str.starts_with("[{\"depth\":2,\"leaf\":\"aa"));
        assert!(current_str.contains("\"root\":\"bb"));
        let expected_tail = format!("\"valid_roots\":[\"{}\"]}}]", "ee".repeat(32));
        assert!(current_str.ends_with(&expected_tail));
    }

    #[test]
    fn several_augmented_proofs_serialize_to_the_wire_text() {
        let proof =
            |leaf: &str, root: &str, leaf_index, depth, elements: &[&str], indices: &[u8]| {
                native::ProofJson {
                    leaf: leaf.into(),
                    root: root.into(),
                    leaf_index,
                    depth,
                    path_elements: elements.iter().map(|e| (*e).to_owned()).collect(),
                    path_indices: indices.to_vec(),
                }
            };
        let proofs = vec![
            proof("a1", "r1", 0, 1, &["p1", "p2"], &[1, 0]),
            proof("a\"2\\", "r2", u64::MAX, u32::MAX, &[], &[]),
            proof("é\u{1}", "", 7, 3, &["x"], &[255]),
        ];
        let roots_array = serde_json::json!(["e1", "e2"]);
        let current = proofs_with_roots_json(&proofs, &roots_array);
        assert_eq!(
            current,
            r#"[{"depth":1,"leaf":"a1","leaf_index":0,"path_elements":["p1","p2"],"path_indices":[1,0],"root":"r1","valid_roots":["e1","e2"]},{"depth":4294967295,"leaf":"a\"2\\","leaf_index":18446744073709551615,"path_elements":[],"path_indices":[],"root":"r2","valid_roots":["e1","e2"]},{"depth":3,"leaf":"é\u0001","leaf_index":7,"path_elements":["x"],"path_indices":[255],"root":"","valid_roots":["e1","e2"]}]"#
        );
        let roundtrip: Vec<serde_json::Value> = proofs
            .iter()
            .map(|p| {
                let mut obj = match serde_json::to_value(p).unwrap() {
                    serde_json::Value::Object(obj) => obj,
                    other => panic!("a proof serializes to an object, got {other}"),
                };
                obj.insert("valid_roots".to_owned(), roots_array.clone());
                serde_json::Value::Object(obj)
            })
            .collect();
        assert_eq!(current, serde_json::Value::Array(roundtrip).to_string());
        assert_eq!(proofs_with_roots_json(&[], &roots_array), "[]");
    }

    #[test]
    fn a_listed_config_on_another_network_is_refused() {
        let devnet_config = "9d6c0f59718f05ecb3f6ae58259821bfff6594e20866d6cd2a214c53e4ec0511";
        assert!(network_conflict(Some("devnet"), devnet_config).is_none());
        let reason = network_conflict(Some("testnet"), devnet_config).expect("conflict");
        assert!(reason.contains("on network devnet") && reason.contains("bound to testnet"));
        assert!(network_conflict(None, devnet_config).is_none());
        assert!(network_conflict(Some("testnet"), &"ab".repeat(32)).is_none());
    }

    #[test]
    fn merkle_proofs_input_validation_shortcircuits() {
        assert_eq!(get_merkle_proofs_impl("cfg", "notjson"), "");
        assert_eq!(get_merkle_proofs_impl("cfg", "{}"), "");
        assert_eq!(get_merkle_proofs_impl("cfg", "[]"), "[]");
        assert_eq!(get_merkle_proofs_impl("cfg", "[\"x\"]"), "");
    }
}
